from flask import Flask, flash, redirect, render_template_string, request, url_for

app = Flask(__name__)
app.config["SECRET_KEY"] = "local-practice-only"

@app.route("/contact", methods=["GET", "POST"])
def contact():
    if request.method == "POST":
        email = request.form.get("email", "").strip()
        if "@" not in email:
            return "Enter a valid email", 400
        flash("Form accepted")
        return redirect(url_for("contact"), code=303)
    return render_template_string("<form method='post'><label>Email <input name='email'></label><button>Send</button></form>")
